// === Tab: mySketch ===
/*
Eclipse (Smooth Fade Transition Version)
Joe 20250714
*/

let y;

// --- 新增的状态管理变量 ---
let animationState; // 'drawing' 或 'fading'
let fadeAlpha;      // 用于控制渐变透明度

function setup() {
	describe(`A grayscale generative art image of a total solar eclipse. The scene animates, then smoothly fades to black before regenerating a new, unique scene.`);
	createCanvas(500, 700);
	background(30);

	// 初始化/重置所有变量
	y = random(300, 400);
	animationState = 'drawing';
	fadeAlpha = 0;

	// 绘制日冕（这部分不变）
	let sunX = random(100, width - 100);
	let sunY = random(50, 150);
	let sunD = random(30, 50);

	push();
	translate(sunX, sunY);
	for (let i = 0; i < 4000; i++) {
		let r = sunD + random(random()) * 15;
		let theta = random(2 * PI);
		let x = cos(theta) * r;
		var y = sin(theta) * r;
		fill(255, 30);
		noStroke();
		circle(x, y, random(2));
	}
	pop();
}

function draw() {

	// 根据当前状态执行不同操作
	if (animationState === 'drawing') {
		// --- 状态1: 正常绘制动画 ---

		for (let x = 0; x < width; x++) {
			let n1 = noise(x * 0.002, y * 0.008);
			let n2 = noise(x * 0.01 + 1000000, y * 0.01 + 1000000);
			let n3 = noise(x * 0.002 + 10000, y * 0.01 + 10000);

			let h = 10 + n1 * 150;

			noStroke();
			fill(n1 * 255 + random(-5, 5));
			rect(x, y, 3, -h);

			if (random() < 0.01 && n2 < 0.4) {
				fill(0, 5);
				rect(x, y - h, randomGaussian(5, 3), -randomGaussian(300, 10));
			}

			if (n3 > 0.5 && n3 < 0.51) {
				for (let j = 0; j < 100; j++) {
					let dotX = x;
					let dotY = y - h - (random(random()) * 200);
					fill(255, 5);
					circle(dotX, dotY, random(2));
				}
			}
		}

		y++;

		// 当动画滚动出屏幕时，切换到 'fading' 状态
		if (y > height + 200) {
			animationState = 'fading';
		}

	} else if (animationState === 'fading') {
		// --- 状态2: 渐变至黑色 ---

		// 绘制一个半透明的黑色矩形，并逐渐增加其不透明度
		fill(0, fadeAlpha);
		noStroke();
		rect(0, 0, width, height);

		fadeAlpha += 4; // 控制渐变速度，数值越大越快

		// 当画面完全变黑后，调用 setup() 重新开始
		if (fadeAlpha >= 255) {
			setup();
		}
	}
}

